WFJ.Data.add("spell", {
  [473384] = { "手引書を使ってArgent Squireを呼び出し、Silithidとの戦闘訓練を行います。従者のいる前でSilithidを倒すと、Argent Dawnとの評判が上昇します。", "従者が同行しています。Silithidsを倒すとArgent Dawnの評判を得られます。", 0xec5a51f0, 0x70ae3586, "uu" },
  [473387] = { "近くのパーティまたはレイドメンバーを鼓舞し、呪文のクリティカル率を$N1%、近接と遠隔のクリティカル率を$N2%、攻撃力を$N3上昇させます。効果時間は$D1です。同様のワールド効果とは重複せず、Chronoboonsの影響を受けません。", "呪文のクリティカル率が$N1%、近接攻撃と遠隔攻撃のクリティカル率が$N2%上昇し、攻撃力が$N3増加します。", 0x87cc436e, 0x04d1ed33, "uu" },
  [473399] = { "歌う花を召喚し、$D1の間、パーティまたはレイドメンバー全員の近接、遠隔、呪文のクリティカル率を$N1%、能力値を$N2上昇させます。同様のワールド効果とは重複しません。Chronoboonsの影響を受けません。", "近接攻撃、遠隔攻撃、呪文のクリティカル率が$N1%上昇し、すべての能力値が$N2増加します。", 0x6a7a8d25, 0x1e139466, "uu" },
  [473403] = { "$D1の間、近くのパーティまたはレイドメンバー全員の攻撃力を$N1、スタミナを$N2%、呪文のクリティカル率を$N3%上昇させます。同様のワールド効果とは重複しません。Chronoboonsの影響を受けません。", "攻撃力が$N1、スタミナが$N2%、呪文のクリティカル率が$N3%上昇します。", 0xb78582ac, 0x23a55955, "uu" },
  [473441] = { "体力が$N1増加します。近接攻撃の速度が$N2%上昇します。5秒ごとにマナを$N3回復します。", "最大体力が$N1増加します。近接攻撃のヘイストが$N2%上昇します。5秒ごとに$N3のマナを回復します。", 0xc53fc1df, 0xc53fc1df, "uu" },
  [473450] = { "$D1の間、パーティまたはレイドメンバー全員の与えるダメージを$N1%増加させます。", "ダメージが$N1%増加します。", 0x74575d7f, 0x416dea0f, "uu" },
  [473466] = { "$D1の間、Firewaterの大釜を召喚します。パーティーまたはレイドの全メンバーが使用でき、$D2の間、近接攻撃力が$N2上昇し、体が大きくなります。", nil, 0x0fcd9860, nil, "um" },
  [473469] = { "$D1の間、近接攻撃力が$N1上昇し、体が大きくなります。", "体が大きくなり、近接攻撃力が$N1増加します。", 0x1f3c4cc7, 0x1bbffd49, "uu" },
  [473476] = { "$D1の間、パーティまたはレイドメンバー全員の移動速度を$N1%、能力値を$N2%上昇させます。", "移動速度が$N1%、すべての能力値が$N2%上昇します。", 0x2d11f2b5, 0x0d29e698, "uu" },
  [473482] = { "SilithusにいるAbyssal CouncilのElementalのメンバーを弱らせ、彼らが与えるすべてのダメージを$N1%減少させます。効果時間は$D1です。", "与えるダメージが$N1%減少しています。", 0x093a0b91, 0x618d76ee, "uu" },
  [473493] = { "近くの場所に罠を設置し、Hive'Ashi、Hive'Regal、Hive'ZoraのSilithidが近づくと爆発して、そのSilithidに$D2の間、$N2秒ごとに体力の$N1%のダメージを与えます。", nil, 0xc93b98f4, nil, "um" },
  [473496] = { nil, "$N2秒ごとに体力の$N1%に相当するFireダメージを受けています。", nil, 0xcf9f5348, "mu" },
  [473525] = { "Hive'Ashi、Hive'Regal、Hive'Zoraの巣の中にいるSilithidを$D1凍りつかせます。ダメージを受けると効果は解除されます。", nil, 0x3bfe5a1c, nil, "um" },
  [473544] = { "この香を吸い込むと影の中に溶け込み、Hive'Ashi、Hive'Regal、Hive'Zoraの中を忍び歩けるようになりますが、速度が$N1%低下します。効果時間は$D1です。", "隠密状態です。移動速度が$N1%低下しています。", 0x2b7ea238, 0xbaa2cba7, "uu" },
  [473561] = { "古代のロープを投げてHive'Ashi、Hive'Regal、Hive'Zoraのsilithidを拘束し、自分のほうへ引き寄せます。レベル$N1より高い敵や、ボスとされている敵には使用できません。", nil, 0xcf940655, nil, "um" },
  [473570] = { nil, "Stunに対する免疫があります。", nil, 0xfd2ef3a2, "mu" },
  [473687] = { nil, "パーティまたはレイドにargent squireがいる間、Hive'Ashi、Hive'Regal、Hive'Zoraでsilithidを倒すとArgent Dawnの評判が上がります。", nil, 0x3775c508, "mu" },
  [473701] = { "対象を挑発して自分を攻撃させます。ただし、対象がすでに自分を攻撃している場合は効果がありません。", "挑発されています。", 0x71de38fd, 0x36f56123, "uu" },
  [473702] = { "枝を使ってAncient of Warを呼び出し、Silithidとの戦いに加勢させます。", nil, 0x65c2a94b, nil, "um" },
